export interface NotesFolder {
  id: string;
  name: string;
  /** Built-in folders (cannot be renamed/deleted) */
  system?: boolean;
}

export interface Note {
  id: string;
  title: string;
  content: string;
  updatedAt: number;

  // Lightweight metadata for list rendering
