  return {
    getItem(key: string) {
      return store.has(key) ? store.get(key)! : null;
    },
    setItem(key: string, value: string) {
      store.set(key, value);
    },
    removeItem(key: string) {
      store.delete(key);
    },
    clear() {
      store.clear();
    },
  };
}

describe('Notes trash restoration order', () => {
  beforeEach(() => {
    vi.resetModules();
    Object.defineProperty(globalThis, 'localStorage', {
      value: createLocalStorageMock(),
      configurable: true,
    });
  });

  it('restores equal-time notes with their original records and stable order', async () => {
    const TimeService = await import('../os/TimeService');
    const { selectTrashedNotes, selectVisibleNotes, useNotesStore } = await import('../system/Notes/state');

    const updatedAt = TimeService.parseToTimestamp('2026-02-25T16:00:00');
    const originalNotes: Note[] = [
      { id: 'amber', title: 'AM220 Amber target', content: 'equal-time first', updatedAt, folderId: 'unfiled' },
      { id: 'lilac', title: 'AM220 Lilac target', content: 'equal-time second', updatedAt, folderId: 'unfiled' },
      { id: 'cobalt', title: 'AM220 Cobalt target', content: 'equal-time third', updatedAt, folderId: 'unfiled' },
    ];
    useNotesStore.setState({ notes: originalNotes });

    TimeService.useSimulatedTime('2026-02-25T17:01:00', false);
    useNotesStore.getState().deleteNote('lilac');
    TimeService.useSimulatedTime('2026-02-25T17:02:00', false);
    useNotesStore.getState().deleteNote('cobalt');
    TimeService.useSimulatedTime('2026-02-25T17:03:00', false);
    useNotesStore.getState().deleteNote('amber');

    const trashedNotes = selectTrashedNotes(useNotesStore.getState());
    expect(trashedNotes.map(note => note.id)).toEqual(['amber', 'cobalt', 'lilac']);

    trashedNotes.forEach(note => useNotesStore.getState().restoreNote(note.id));

    const restoredNotes = selectVisibleNotes(useNotesStore.getState());
    expect(restoredNotes.map(note => note.id)).toEqual(['amber', 'lilac', 'cobalt']);
    expect(restoredNotes).toEqual(originalNotes);
  });
});

